<style>.cat-admin-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.cat-stat strong{display:block;font-size:2rem}.cat-stat span{color:#64748b}.cat-actions{display:flex;gap:.5rem;flex-wrap:wrap}@media(max-width:800px){.cat-admin-grid{grid-template-columns:1fr 1fr}}</style>
<div class="cat-admin-grid"><div class="card cat-stat"><strong><?= (int) $counts['new'] ?></strong><span>New inquiries</span></div><div class="card cat-stat"><strong><?= (int) $counts['all'] ?></strong><span>Total inquiries</span></div><div class="card cat-stat"><strong><?= (int) $counts['items'] ?></strong><span>Menu items</span></div><div class="card cat-stat"><strong><?= (int) $counts['packages'] ?></strong><span>Packages</span></div></div>
<div class="card"><h2 style="margin-top:0">Manage catering</h2><div class="cat-actions"><a class="btn" href="<?= e_attr($basePath) ?>/admin/catering/menus">Menus</a><a class="btn" href="<?= e_attr($basePath) ?>/admin/catering/packages">Packages</a><a class="btn" href="<?= e_attr($basePath) ?>/admin/catering/inquiries">Leads</a><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/catering/settings">Settings</a><a class="btn secondary" href="<?= e_attr($basePath) ?>/" target="_blank" rel="noopener">View website</a></div></div>
